import json
from pathlib import Path

TOPICS=[]

def q(stem, options, answer, explanation, level=1):
    return dict(stem=stem, options=options, answer=answer, explanation=explanation, level=level)

def add(id, title, blurb, objectives, sections, example, pitfall, source, cards, questions, time=12):
    TOPICS.append(dict(id=id, order=len(TOPICS)+1,title=title,blurb=blurb,minutes=time,objectives=objectives,
        sections=[{'heading':h,'body':body} for h,body in sections],
        example={'title':example[0],'situation':example[1],'reasoning':example[2],'conclusion':example[3]},
        pitfall=pitfall,source=source,
        cards=[{'id':id+'-c'+str(i+1),'front':front,'back':back} for i,(front,back) in enumerate(cards)],
        questions=[dict(x,id=id+'-q'+str(i+1)) for i,x in enumerate(questions)]))

add('zaklady','Základy ekonomie',
    'Vzácnost, alternativní náklady, pozitivní a normativní výroky a hranice produkčních možností.',
    ['Vysvětlit, proč ekonomie řeší volbu mezi možnostmi.','Rozlišit popis reality od hodnotového soudu.','Použít hranici produkčních možností.'],
    [('Vzácnost a volba','Zdroje (čas, práce, půda i kapitál) jsou omezené. Každé rozhodnutí proto znamená, že se vzdáme jiné možnosti. Náklad obětované příležitosti je hodnota nejlepší nevyužité alternativy.'),
     ('Pozitivní a normativní ekonomie','Pozitivní výrok popisuje, jak ekonomika funguje nebo co se stalo; lze jej ověřovat daty. Normativní výrok vyjadřuje, co by se mělo stát, a obsahuje hodnotové hledisko.'),
     ('Hranice produkčních možností (PPF)','Bod na hranici znamená efektivní využití dostupných zdrojů; bod uvnitř ukazuje nevyužitý potenciál. Bod vně je při daných zdrojích a technologiích nedosažitelný.')],
    ('Volba studenta','Máš tři hodiny a můžeš jít na brigádu nebo se připravovat na test.','Pokud zvolíš učení, vzdáváš se nejlepší alternativy, například výdělku z brigády.','Ekonomický náklad volby není vždy jen zaplacená cena.'),
    'Nezaměňuj pozitivní výrok s „pozitivním hodnocením“. Pozitivní ekonomie může popisovat i špatnou situaci.',
    'Sýkora: Úvod do ekonomického studia, seminář č. 1; Dohnalová a Dobeš: Mikroekonomie I (2013).',
    [('Co je vzácnost?','Omezenost zdrojů vzhledem k potřebám a přáním.'),('Co jsou náklady obětované příležitosti?','Hodnota nejlepší alternativy, které se vzdáváme.'),('Pozitivní vs. normativní výrok?','Pozitivní lze ověřit; normativní říká, co by mělo být.'),('Co značí bod uvnitř PPF?','Neefektivní využití dostupných zdrojů.')],
    [q('Co nejlépe vystihuje náklad obětované příležitosti?',['Všechny výdaje na vybranou možnost','Hodnota nejlepší odmítnuté alternativy','Součet všech možných výdělků','Pouze finanční cena volby'],1,'Při volbě se vzdáváme nejlepší jiné dostupné možnosti.'),
     q('Který výrok je normativní?',['Nezaměstnanost dosáhla 4 %.','Inflace se proti loňsku snížila.','Stát by měl zvýšit podporu studentů.','Průměrná mzda meziročně vzrostla.'],2,'Slovo „měl“ vyjadřuje žádoucí stav; jde o hodnotové tvrzení.'),
     q('Co vyjadřuje bod pod hranicí produkčních možností?',['Nedosažitelnou kombinaci','Efektivní kombinaci','Nevyužité zdroje','Maximální produkci obou statků'],2,'Bod uvnitř PPF lze při daných zdrojích zlepšit.'),
     q('Co patří mezi výrobní faktory?',['Práce, půda a kapitál','Daň, clo a dotace','Poptávka, nabídka a cena','Spotřeba, úspora a inflace'],0,'Práce, půda a kapitál se používají při výrobě statků a služeb.'),
     q('Která změna může posunout hranici produkčních možností ven?',['Pokles využití strojů','Zlepšení technologie','Pouhý přesun produkce mezi statky','Přesun do bodu uvnitř hranice'],1,'Nová technologie umožní více výstupu ze stejných vstupů.',2),
     q('Jaké otázky řeší základní ekonomický problém?',['Kdo vyhraje, kdo prohraje a proč','Co, jak a pro koho vyrábět','Kdy, kde a proč spořit','Kolik, kde a kdy utratit'],1,'Ekonomika rozhoduje o výběru produktů, metod výroby a rozdělení výsledků.')])

add('trzni-mechanismus','Trh a tržní mechanismus',
    'Poptávka, nabídka, jejich posuny, rovnováha a cenová elasticita.',
    ['Rozlišit pohyb po křivce a posun celé křivky.','Určit vliv změny poptávky na cenu a množství.','Vysvětlit význam elasticity.'],
    [('Poptávka a nabídka','Při ostatních nezměněných podmínkách platí, že s vyšší cenou poptávané množství obvykle klesá a nabízené množství roste. Tržní cena se ustavuje vzájemným působením prodávajících a kupujících.'),
     ('Pohyb versus posun','Změna vlastní ceny výrobku způsobuje pohyb po dané poptávkové nebo nabídkové křivce. Změna důchodu, preferencí, cen vstupů či technologie může posunout celou křivku.'),
     ('Elasticita','Cenová elasticita poptávky popisuje procentní reakci poptávaného množství na procentní změnu ceny. Nízká absolutní elasticita znamená, že množství reaguje slabě.')],
    ('Trh s pečivem','Nová pec sníží pekárnám náklady na kus pečiva.','Při každé ceně mohou nabízet více; nabídka se posouvá doprava.','Při nezměněné poptávce bývá výsledkem nižší rovnovážná cena a vyšší množství.'),
    'Když se zvýší cena výrobku, poptávková křivka se sama o sobě neposouvá: mění se poptávané množství na stávající křivce.',
    'Sýkora: Trh a tržní mechanismus, seminář č. 2; Dohnalová a Dobeš: Mikroekonomie I (2013).',
    [('Co je rovnovážná cena?','Cena, při které se poptávané množství rovná nabízenému.'),('Co posouvá poptávku?','Například změna důchodů, preferencí nebo cen souvisejících statků.'),('Co je cenová elasticita?','Poměr procentní změny množství k procentní změně ceny.'),('Jak se liší posun nabídky od pohybu po nabídce?','Posun mění podmínky nabídky; pohyb vyvolá změna vlastní ceny.')],
    [q('Co se při růstu vlastní ceny statku obvykle stane s poptávaným množstvím?',['Vzroste','Klesne','Zůstane vždy stejné','Poptávková křivka se posune doprava'],1,'Při nezměněných ostatních faktorech se pohybujeme po klesající poptávkové křivce.'),
     q('Která událost může posunout nabídku zboží doprava?',['Zvýšení ceny výrobku','Zvýšení mzdových nákladů výroby','Zlevnění vstupů do výroby','Zákaz nové technologie'],2,'Nižší výrobní náklady umožní nabízet více při stejné ceně.'),
     q('Při ceně pod rovnováhou vzniká na standardním trhu spíše…',['Nedostatek zboží','Přebytek zboží','Zánik poptávky','Dokonalá konkurence'],0,'Poptávané množství převyšuje nabízené.'),
     q('Poptávka má absolutní cenovou elasticitu 0,4. Jde o poptávku…',['Elastickou','Jednotkově elastickou','Dokonale elastickou','Neelastickou'],3,'Absolutní elasticita menší než 1 znamená slabší procentní reakci množství.'),
     q('Při nezměněné nabídce roste poptávka. Co typicky nastane?',['Nižší cena a nižší množství','Vyšší cena a vyšší množství','Nižší cena a vyšší množství','Vyšší cena a nižší množství'],1,'Posun poptávky doprava zvýší rovnovážnou cenu i množství.',2),
     q('Co vyvolá pohyb po existující nabídkové křivce?',['Změna technologie','Změna vlastní ceny produktu','Změna daně z výroby','Změna ceny energií'],1,'Samotná cena výstupu mění nabízené množství; ostatní faktory posouvají nabídku.')])

add('spotrebitel','Spotřebitel a poptávka',
    'Užitek, mezní užitek, rozpočtové omezení, indiferenční křivky.',
    ['Rozlišit celkový a mezní užitek.','Popsat roli rozpočtového omezení.','Vysvětlit substituční a důchodový efekt změny ceny.'],
    [('Užitek','Celkový užitek vyjadřuje celkové uspokojení spotřebitele. Mezní užitek je dodatečné uspokojení z další jednotky; často klesá, když spotřebováváme stále více stejného statku.'),
     ('Rozpočet a volba','Spotřebitel chce dosáhnout co nejvyššího uspokojení s omezeným důchodem. Rozpočtová přímka ukazuje dostupné kombinace statků při daných cenách a příjmu.'),
     ('Indiferenční křivky','Každý bod na jedné indiferenční křivce představuje spotřebiteli stejně preferovanou kombinaci dvou statků. Optimální volba bývá v bodě dotyku dosažitelné indiferenční křivky s rozpočtovou přímkou.')],
    ('První a čtvrtá káva','První káva po ránu tě potěší víc než čtvrtá za sebou.','Celkový užitek ještě může růst, ale dodatečný užitek z další kávy klesá.','Nezaměňuj přírůstek užitku s celkovým užitkem.'),
    'Klesající mezní užitek neznamená, že každá další jednotka má záporný užitek.',
    'Sýkora: Chování spotřebitele a formování poptávky, seminář č. 3; Dohnalová a Dobeš: Mikroekonomie I (2013).',
    [('Co vyjadřuje mezní užitek?','Přírůstek celkového užitku při spotřebě další jednotky.'),('Co omezuje spotřebitelovu volbu?','Důchod a ceny jednotlivých statků.'),('Co znamená indiferenční křivka?','Kombinace statků, které spotřebitel považuje za stejně dobré.'),('Co je substituční efekt?','Změna spotřeby v důsledku změny relativních cen při kompenzované kupní síle.')],
    [q('Mezní užitek druhé sušenky je…',['Celkový užitek z obou sušenek','Změna užitku po snědení druhé sušenky','Cena druhé sušenky','Užitek všech dostupných statků'],1,'Mezní užitek měří přírůstek oproti předchozí spotřebě.'),
     q('Co ukazuje rozpočtová přímka?',['Pouze nejdražší nákupy','Množství výrobků na trhu','Dostupné kombinace dvou statků při daném příjmu a cenách','Počet nakupujících'],2,'Všechny body na přímce vyčerpávají rozpočet při daných cenách.'),
     q('Když se zvýší příjem a ceny se nezmění, rozpočtová přímka se obvykle…',['Posune rovnoběžně ven','Posune rovnoběžně dovnitř','Nutně otočí kolem počátku','Změní v indiferenční křivku'],0,'Vyšší příjem umožňuje více obou statků při stejných cenách.'),
     q('Co platí pro body na stejné indiferenční křivce?',['Mají stejnou cenu','Poskytují stejnou úroveň preferovaného užitku','Vyžadují stejné množství každého statku','Všechny jsou dostupné'],1,'Indiferenční křivka spojuje stejně preferované kombinace.'),
     q('Při rostoucí spotřebě jedné potraviny mezní užitek typicky…',['Zůstává vždy stejný','Neustále roste','Klesá','Je automaticky záporný'],2,'Zákon klesajícího mezního užitku popisuje klesající dodatečné uspokojení.'),
     q('Substituční efekt při zlevnění statku znamená, že spotřebitel…',['Tento statek relativně častěji volí místo alternativ','Má vždy nižší nominální příjem','Musí přestat nakupovat ostatní statky','Přestane řešit relativní ceny'],0,'Zlevněný statek se vůči alternativám stává výhodnějším.',2)])

add('firma','Firma, výroba a náklady',
    'Produkční funkce, mezní produkt, fixní a variabilní náklady, MR a MC.',
    ['Rozlišit krátké a dlouhé období.','Vypočítat a interpretovat mezní náklady a mezní produkt.','Propojit produkci s maximalizací zisku.'],
    [('Vstupy a výstup','Produkční funkce Q = f(K, L) ukazuje vztah mezi kapitálem, prací a produkcí. V krátkém období je alespoň jeden vstup fixní; v dlouhém období lze měnit všechny vstupy.'),
     ('Náklady','Fixní náklady (FC) se s objemem výroby v daném období nemění. Variabilní náklady (VC) naopak reagují na produkci. Celkové náklady TC = FC + VC. Mezní náklady MC ukazují náklad na další jednotku produkce.'),
     ('Rozhodnutí o produkci','Firma maximalizující zisk volí produkci, kde se mezní příjem MR rovná mezním nákladům MC, splňují-li se příslušné podmínky. Před dosažením tohoto bodu se zvýšení výroby může vyplatit, pokud MR > MC.')],
    ('Malá pekárna','Pekař má jednu pec a přijme dalšího pracovníka.','První další pracovník může zvýšit výstup výrazně, ale později se lidé u jedné pece překážejí.','Mezní produkt dalšího pracovníka při fixním kapitálu může postupně klesat.'),
    'Mezní náklad není totéž co průměrný náklad; rozhodnutí o poslední jednotce vyžaduje sledovat přírůstek.',
    'Sýkora: Nabídka na trhu výrobků a služeb, seminář č. 4; Dohnalová a Dobeš: Mikroekonomie I (2013).',
    [('Produkční funkce?','Vztah mezi vstupy (např. prací a kapitálem) a množstvím produkce.'),('Fixní vs. variabilní náklad?','Fixní se v daném období nemění s Q, variabilní ano.'),('MC je…','Přírůstek celkových nákladů na další jednotku produkce.'),('Pravidlo maximalizace zisku?','Při vnitřním optimu MR = MC.')],
    [q('Který náklad bývá v krátkém období fixní?',['Spotřebovaná mouka','Úkolová mzda výrobního dělníka','Nájem výrobní haly','Spotřeba materiálu na kus'],2,'Nájem haly se krátkodobě nemění s počtem vyrobených kusů.'),
     q('Jaké pravidlo určuje vnitřní optimum produkce firmy maximalizující zisk?',['MR = MC','P = 0','TC = VC','FC = MC'],0,'Firma porovnává přírůstek příjmů a nákladů další jednotky.'),
     q('Při nárůstu výroby z 10 na 11 kusů vzrostou náklady z 900 na 980 Kč. Mezní náklad posledního kusu je…',['980 Kč','90 Kč','80 Kč','1 880 Kč'],2,'MC = změna TC / změna Q = (980 − 900) / 1 = 80 Kč.',2),
     q('Co vyjadřuje mezní produkt práce?',['Přírůstek produkce po přidání jednotky práce','Příjem firmy ze všech zaměstnanců','Průměrnou mzdu','Náklady na stroje'],0,'MP práce vyjadřuje dodatečný výstup další jednotky práce.'),
     q('Když jsou FC = 400 Kč a VC = 600 Kč, celkové náklady jsou…',['200 Kč','1 000 Kč','600 Kč','2 400 Kč'],1,'TC = FC + VC = 400 + 600 = 1 000 Kč.'),
     q('Co platí o dlouhém období v teorii firmy?',['Všechny výrobní vstupy mohou být variabilní','Mzdy musí být fixní','Všechny firmy mají nulové náklady','Nelze změnit kapacitu'],0,'Dlouhé období umožňuje měnit i kapitál a výrobní kapacitu.')])

add('dokonala-konkurence','Dokonalá konkurence',
    'Model cenového příjemce, rovnováha firmy a dlouhodobé přizpůsobení.',
    ['Určit rozdíl mezi trhem a jednotlivou firmou.','Použít podmínku P = MR = MC.','Odlišit ekonomický od účetního zisku.'],
    [('Cenový příjemce','Dokonale konkurenční firma je malá vzhledem k trhu, prodává homogenní produkt a nemůže ovlivnit tržní cenu. Pro jednotlivou firmu platí P = MR = AR.'),
     ('Optimální množství','Pro vnitřní optimum firmy, která maximalizuje zisk, platí P = MC na rostoucí části příslušné křivky MC. V krátkém období může firma vyrábět i při ekonomické ztrátě, pokud pokryje variabilní náklady.'),
     ('Dlouhé období','Volný vstup a výstup firem vede za standardních předpokladů k nulovému ekonomickému zisku. To neznamená nulový účetní zisk: náklady příležitosti jsou již zahrnuté v ekonomických nákladech.')],
    ('Pěstitel obilí','Farmář prodává téměř identické obilí za tržní cenu, kterou sám neovlivní.','Další tunu vyrobí jen pokud příjem z ní pokryje mezní náklady.','Cenu určuje trh, firma volí hlavně množství.'),
    'Nulový ekonomický zisk není totéž co „firma nic nevydělává“: zahrnuje obvyklou odměnu alternativních zdrojů.',
    'Sýkora: Firma v podmínkách dokonalé konkurence, seminář č. 5; Dohnalová a Dobeš: Mikroekonomie I (2013).',
    [('Co znamená cenový příjemce?','Jednotlivá firma přijímá tržní cenu jako danou.'),('Co platí pro MR firmy?','V dokonalé konkurenci MR = P.'),('Kdy firma krátkodobě přeruší výrobu?','Při ceně pod minimem průměrných variabilních nákladů (ve standardním modelu).'),('Co znamená nulový ekonomický zisk?','Výnosy pokryjí explicitní i implicitní ekonomické náklady.')],
    [q('Jak se chová jednotlivá dokonale konkurenční firma vůči ceně?',['Sama ji běžně stanovuje','Přijímá ji z trhu','Určuje ji vládním nařízením','Mění ji bez dopadu na prodej'],1,'Jednotlivá firma má vzhledem k trhu zanedbatelnou tržní sílu.'),
     q('Co v dokonalé konkurenci platí pro mezní příjem MR?',['MR = P','MR je vždy nulový','MR je vždy vyšší než P','MR = FC'],0,'Další jednotka se prodá za danou tržní cenu.'),
     q('Jaký vztah platí pro vnitřní optimum produkce firmy v dokonalé konkurenci?',['P = MC','P = FC','AR = AVC vždy','VC = 0'],0,'P = MR a pro optimum MR = MC.'),
     q('Když cena klesne pod minimum AVC, firma v krátkém období typicky…',['Zvýší produkci','Přeruší výrobu','Vstoupí na nový trh','Vyrábí maximálně'],1,'Příjmy nepokryjí ani variabilní náklady produkce.',2),
     q('Dlouhodobý ekonomický zisk ve standardním modelu dokonalé konkurence směřuje k…',['Trvale vysokému zisku','Záporné nekonečné ztrátě','Nule','Zisku rovnému tržbám'],2,'Volný vstup firem při zisku a výstup při ztrátě vytvářejí tlak na nulový ekonomický zisk.'),
     q('Co je homogenní produkt?',['Každá firma má odlišný design','Produkty různých firem jsou pro spotřebitele zaměnitelné','Produkt je veřejný statek','Produkt má individuální patent'],1,'Dokonalá konkurence předpokládá stejnorodé a zaměnitelné produkty.')])

add('monopol','Monopol',
    'Tržní síla, bariéry vstupu, mezní příjem a neefektivnost monopolu.',
    ['Vysvětlit příčiny vzniku monopolu.','Rozlišit cenu a mezní příjem.','Popsat dopad na množství a cenu.'],
    [('Jediný prodávající','Monopol ovládá nabídku produktu bez blízkých substitutů. Může vznikat vlivem patentů, kontrolou důležitého zdroje nebo úsporami z rozsahu a bariérami vstupu.'),
     ('Cenové rozhodnutí','Monopol čelí klesající tržní poptávce. K prodeji další jednotky obvykle musí snížit cenu, takže mezní příjem MR leží pod cenou P. Optimální množství určí při MR = MC a cenu odečte z poptávky.'),
     ('Důsledky','Ve srovnání se standardním konkurenčním modelem monopol typicky omezuje výstup a účtuje vyšší cenu; tím může vznikat ztráta mrtvé váhy.')],
    ('Jediná vodárenská síť','Budování několika paralelních vodovodních sítí by bylo nákladné.','Úspory z rozsahu mohou učinit jednoho dodavatele efektivnějším než několik.','Takový přirozený monopol může podléhat regulaci.'),
    'Monopol není firma, která „může stanovit libovolně vysokou cenu“. Vysokou cenu omezuje ochota zákazníků platit.',
    'Sýkora: Nedokonalá konkurence – monopol, seminář č. 6; Dohnalová a Dobeš: Mikroekonomie I (2013).',
    [('MR ve vztahu k ceně u monopolu?','Při klesající poptávce MR < P.'),('Co jsou bariéry vstupu?','Překážky omezující vstup nových konkurentů na trh.'),('Co je přirozený monopol?','Situace, kdy jeden producent díky nákladům obslouží trh levněji než několik.'),('Jak monopol volí cenu?','Zvolí množství při MR = MC a odpovídající cenu na poptávkové křivce.')],
    [q('Který faktor může vytvořit bariéru vstupu do odvětví?',['Volný vstup všech firem','Patent na technologii','Dokonale stejné výrobky','Dokonalá informovanost'],1,'Patent může po omezenou dobu chránit výrobní postup.'),
     q('Jaký vztah zpravidla platí u monopolu s klesající poptávkou?',['MR > P','MR = P vždy','MR < P','MR = FC'],2,'Zvýšení prodaného množství vyžaduje nižší cenu, často i u dřívějších jednotek.'),
     q('Monopol maximalizující zisk volí množství zpravidla tam, kde…',['MR = MC','P = 0','P = AC vždy','TR = TC vždy'],0,'I monopol hledá množství, kde se mezní příjem rovná mezním nákladům.'),
     q('Co je příkladem přirozeného monopolu?',['Stánky s ovocem','Distribuční síť s vysokými fixními náklady','Trh s identickým obilím','Mnoho nezávislých kaváren'],1,'Vysoké fixní náklady sítě a úspory z rozsahu mohou favorizovat jedinou síť.'),
     q('Co se ve standardním porovnání s dokonalou konkurencí typicky pojí s monopolem?',['Nižší cena a větší množství','Stejná cena a výstup','Vyšší cena a menší množství','Nulová cena'],2,'Tržní síla obvykle vede k omezení výstupu a vyšší ceně.',2),
     q('Ztráta mrtvé váhy monopolu označuje…',['Daň z monopolního zisku','Nerealizované vzájemně výhodné obchody','Veškeré fixní náklady','Úsporu z reklamy'],1,'Část potenciálního společenského přebytku se kvůli omezení množství nevytvoří.')])

add('oligopol','Oligopol',
    'Strategické chování několika velkých firem, konkurence cenou a množstvím.',
    ['Popsat vzájemnou závislost firem.','Rozlišit modely Cournot a Bertrand.','Rozpoznat kartelovou dohodu.'],
    [('Trh několika hráčů','V oligopolu působí několik významných producentů a jejich rozhodnutí se vzájemně ovlivňují. Každá změna ceny či výstupu může vyvolat reakci soupeře.'),
     ('Způsoby soupeření','Cournotův model popisuje soutěž v množství, Bertrandův v ceně a Stackelbergův model zahrnuje sekvenční volbu množství a roli vedoucí firmy.'),
     ('Kartely a teorie her','Firmy se mohou pokoušet koordinovat ceny nebo množství. Kartel může zvýšit jejich společné zisky, ale cenová či tržní dohoda konkurentů bývá nezákonná. Teorie her ukazuje napětí mezi spoluprací a soutěží.')],
    ('Dvě čerpací stanice','Jedna stanice zlevní palivo.','Druhá může reagovat slevou, takže první nezíská výhodu na dlouho.','V oligopolu nestačí znát vlastní náklady; záleží na očekávané reakci konkurenta.'),
    'Nezaměňuj oligopol a monopolistickou konkurenci: oligopol má několik dominantních hráčů.',
    'Sýkora: Nedokonalá konkurence – oligopol, seminář č. 7; Dohnalová a Dobeš: Mikroekonomie I (2013).',
    [('Hlavní znak oligopolu?','Strategická vzájemná závislost malého počtu významných firem.'),('Cournotův model?','Soutěž v množství produkce.'),('Bertrandův model?','Soutěž v cenách.'),('Co je kartel?','Dohoda konkurentů o koordinaci cen, množství nebo trhu.')],
    [q('Čím se především vyznačuje oligopol?',['Jednou firmou bez konkurence','Mnoha cenovými příjemci','Několika vzájemně závislými firmami','Pouze veřejnými podniky'],2,'Rozhodnutí jedné významné firmy ovlivňuje reakce ostatních.'),
     q('V Cournotově modelu firmy strategicky volí zejména…',['Množství','Výši daně','Počet spotřebitelů','Veřejné statky'],0,'Cournotův model je modelem soutěže v objemu produkce.'),
     q('V Bertrandově modelu firmy soupeří především…',['Množstvím','Cenou','Mzdami','Veřejnou regulací'],1,'Bertrandův model formuluje strategickou volbu cen.'),
     q('Co znamená kartel?',['Výběr spotřebitelů','Dohodu konkurentů o omezení soutěže','Pravidla dokonalé konkurence','Náhodný pokles nabídky'],1,'Kartel cíleně koordinuje tržní chování konkurentů.'),
     q('Proč se firma v oligopolu zajímá o reakci konkurenta?',['Protože její výsledek na reakci závisí','Protože neexistuje tržní cena','Protože nemá žádné náklady','Protože musí mít jednotný výrobek'],0,'Zisk firmy ovlivňují i cenová a produkční rozhodnutí soupeřů.'),
     q('Který model výslovně počítá s vůdcem a následovníkem při volbě množství?',['Bertrand','Cournot ve své základní simultánní podobě','Stackelberg','Dokonalá konkurence'],2,'Stackelbergův model zavádí sekvenční rozhodnutí firem.',2)])

add('monopolisticka-konkurence','Monopolistická konkurence',
    'Mnoho producentů, odlišené produkty, marketing a vstup konkurentů.',
    ['Vysvětlit diferenciaci výrobku.','Rozlišit krátkodobý a dlouhodobý ekonomický zisk.','Porovnat s monopolní a dokonalou konkurencí.'],
    [('Odlišení výrobku','Na trhu působí mnoho firem, ale jejich produkty nejsou dokonalé substituty. Značka, umístění, servis nebo design umožňují omezenou tržní sílu.'),
     ('Rozhodnutí firmy','Firma čelí klesající individuální poptávce. Proto bývá MR < P, optimum množství vychází z MR = MC a cenu určí poptávka.'),
     ('Dlouhé období','Volný vstup konkurentů postupně snižuje ekonomický zisk. V běžném modelu platí P = AC > MC a vzniká nevyužitá kapacita oproti minimálním průměrným nákladům.')],
    ('Kavárny ve městě','Kavárny prodávají podobnou kávu, ale liší se atmosférou a polohou.','Hosté někdy přijmou vyšší cenu kvůli oblíbenému prostředí.','Diferenciace umožňuje určitou cenovou volnost i při mnoha konkurentech.'),
    '„Mnoho firem“ neznamená automaticky dokonalou konkurenci. Rozhoduje i to, zda jsou výrobky identické.',
    'Sýkora: Nedokonalá konkurence – monopolistická konkurence, seminář č. 8; Dohnalová a Dobeš: Mikroekonomie I (2013).',
    [('Co je diferenciace produktu?','Odlišení produktu vzhledem, kvalitou, značkou nebo dostupností.'),('Kolik firem bývá v monopolistické konkurenci?','Mnoho firem nabízejících odlišené produkty.'),('Jaký je dlouhodobý ekonomický zisk?','Ve standardním modelu se vstupem konkurentů směřuje k nule.'),('Platí MR = P?','Ne, při klesající individuální poptávce firmy bývá MR < P.')],
    [q('Typickým příkladem monopolistické konkurence jsou…',['Mnohé vzájemně odlišené kavárny','Jediná vodovodní síť','Dvoukolejná burza s danou cenou','Jedna firma s výhradním patentem'],0,'Kavárny se liší značkou, polohou i službami a bývá jich mnoho.'),
     q('Co firmám umožňuje určitou tržní sílu v monopolistické konkurenci?',['Úplná homogenita','Diferenciace produktu','Povinnost jedné ceny všem','Absence zákazníků'],1,'Odlišný produkt není pro zákazníka dokonale zaměnitelný.'),
     q('Co obvykle platí pro dlouhodobý ekonomický zisk?',['Je vždy maximální','Roste bez omezení','Směřuje k nule vstupem firem','Je roven celkovým tržbám'],2,'Vstup konkurenčních firem omezuje původní zisky.'),
     q('Pro firmu s klesající individuální poptávkou obvykle platí…',['MR < P','MR = P vždy','MR > P vždy','P = 0'],0,'Další prodej vyžaduje snížení ceny a mezní příjem je nižší než cena.'),
     q('Na rozdíl od dokonalé konkurence prodávají firmy monopolistické konkurence…',['Výhradně jeden výrobek','Odlišené produkty','Pouze veřejné statky','Pouze suroviny'],1,'Produkty nejsou dokonale homogenní.'),
     q('Neefektivita v dlouhém období může mít podobu…',['P = minimum AC vždy','P = MC vždy','Přebytečné výrobní kapacity','Dokonalé informovanosti'],2,'Firma nemusí vyrábět při minimu průměrných nákladů.',2)])

add('vyrobni-faktory','Trhy výrobních faktorů',
    'Práce, kapitál a půda jako výrobní vstupy; MRP, MFC a jejich odměňování.',
    ['Vysvětlit odvozenou poptávku po výrobním faktoru.','Použít vztah MRP a MFC.','Přiřadit faktorům odpovídající odměny.'],
    [('Poptávka po vstupu je odvozená','Firma potřebuje zaměstnance, stroje či půdu proto, že chce vyrábět a prodávat produkty. Změna poptávky po finálním výrobku proto ovlivňuje poptávku po výrobních faktorech.'),
     ('Mezní příjem produktu','MRP je dodatečný příjem z výstupu vytvořeného další jednotkou vstupu. MFC jsou dodatečné náklady na tuto jednotku. Firma při vnitřním optimu hledá MRP = MFC.'),
     ('Odměna za faktory','Práce je odměňována mzdou, půda rentou a zapůjčený kapitál úrokem. Konkrétní trhy mohou mít nedokonalou konkurenci a vyjednávací sílu.')],
    ('Nový pracovník','Další pracovník umožní firmě získat dodatečné tržby 45 000 Kč za měsíc; firmu celkem stojí 40 000 Kč.','Protože MRP převyšuje MFC, může se jeho přijetí vyplatit, pokud se ostatní faktory nezmění.','Firma najímá vstupy kvůli jejich přínosu k prodejnému výstupu.'),
    'MRP se v nedokonalé konkurenci odvozuje přes mezní příjem výstupu MR, nikoliv automaticky přes jeho cenu.',
    'Sýkora: Trh primárních výrobních faktorů, seminář č. 9; Dohnalová a Dobeš: Mikroekonomie I (2013).',
    [('Co znamená odvozená poptávka?','Poptávka po vstupu závisí na poptávce po produktu, který vstup umožňuje vyrábět.'),('Co je MRP?','Dodatečný příjem vytvořený další jednotkou výrobního faktoru.'),('Co je MFC?','Dodatečný náklad na další jednotku faktoru.'),('Optimální množství vstupu?','V typickém vnitřním optimu MRP = MFC.')],
    [q('Proč firmy poptávají práci a stroje?',['Protože potřebují výrobní vstupy pro produkci','Protože výrobní faktory nemají cenu','Kvůli tržní rovnováze bez výstupu','Jen kvůli legislativě'],0,'Poptávka po faktorech se odvozuje od produktové poptávky.'),
     q('MRP znamená…',['Celkový náklad na celý podnik','Dodatečný příjem z další jednotky vstupu','Průměrný úrok','Fixní příjem domácností'],1,'Marginal Revenue Product je dodatečný příjem vytvořený mezní jednotkou výrobního faktoru.'),
     q('MFC představuje…',['Mezní náklady faktoru','Celkový produkt','Tržní cenu výrobku','Průměrné tržby'],0,'Jde o přírůstek nákladů při využití další jednotky vstupu.'),
     q('Firma v modelovém vnitřním optimu najímá faktor do bodu…',['MRP = MFC','MRP = 0 bez výjimky','MFC = 0 bez výjimky','MFC = celkové tržby'],0,'Srovnává mezní přínos faktoru s mezním nákladem.'),
     q('Která dvojice faktor–odměna je správná?',['Práce–úrok','Půda–renta','Kapitál–mzda','Půda–zisk z dividend'],1,'V tradičním modelu je odměnou za půdu renta.'),
     q('Pokud vzroste poptávka po produktu firmy, poptávka po vstupu může…',['Také vzrůst','Nutně vymizet','Zůstat matematicky vždy nulová','Být vždy nezávislá'],0,'Vyšší prodeje mohou zvýšit mezní příjem vytvářený výrobním faktorem.',2)])

add('trh-prace','Trh práce a mzda',
    'Nabídka pracovní síly, odvozená poptávka firem, rovnovážná mzda a vliv technologií.',
    ['Správně určit, kdo nabízí a kdo poptává práci.','Interpretovat graf rovnováhy trhu práce.','Vysvětlit, proč AI může poptávku po práci posunout oběma směry.'],
    [('Nabídka a poptávka','Pracovní sílu nabízejí domácnosti, zatímco firmy ji poptávají jako vstup do výroby. Cenou práce je mzda. Průsečík tržních křivek označuje modelovou rovnováhu.'),
     ('Produktivita a mzdy','Firma hodnotí, jaký dodatečný příjem získá díky pracovníkovi (MRP). Pokud zlepšení technologie zvýší jeho produktivitu, může růst poptávka po dané kvalifikaci.'),
     ('Technologie a substituce','Automatizace někdy nahradí rutinní úkoly a sníží poptávku po určitých činnostech. Jindy technologie doplní člověka, zvýší jeho produktivitu a poptávku může podpořit. Výsledek závisí i na poptávce po produktech.')],
    ('Automatizace faktur','Účetní oddělení začne používat software na automatické čtení faktur.','Firma může ponechat zaměstnance a přijímat více zakázek, nebo zkrátit potřebu rutinní práce.','Z automatizace jednotlivého úkolu nelze bez dalšího odvodit zánik celé profese.'),
    'Substituční a důchodový efekt individuální nabídky práce není totéž jako substituce lidské práce technologií.',
    'Sýkora: Trh práce a mzda, seminář č. 10; Dohnalová a Dobeš: Mikroekonomie I (2013), kap. 9.',
    [('Kdo nabízí práci?','Domácnosti a jednotlivci.'),('Kdo poptává práci?','Firmy a další zaměstnavatelé.'),('Rovnovážná mzda?','Mzda, při které se množství nabídnuté a poptávané práce vyrovná.'),('Jak AI může ovlivnit poptávku po práci?','Může nahradit některé úkoly, nebo zvýšit přínos lidské práce.'),('Co je monopson na trhu práce?','Trh s jedním dominantním kupujícím pracovní síly.')],
    [q('Kdo je na trhu práce na straně nabídky?',['Zaměstnavatelé','Domácnosti a pracovníci','Pouze stát','Výrobci strojů'],1,'Pracovníci nabízejí své pracovní služby.'),
     q('Kdo tvoří poptávku po práci?',['Firmy a další zaměstnavatelé','Pouze zaměstnanci','Pouze domácnosti','Pouze spotřebitelé'],0,'Firmy najímají práci jako výrobní faktor.'),
     q('Co označuje rovnovážný bod v grafu trhu práce?',['Nejvyšší možnou mzdu','Shodu nabízeného a poptávaného množství práce','Nulové výrobní náklady','Počet nezaměstnaných'],1,'V průsečíku S a D se tržní množství nabídnuté a poptávané práce rovnají.'),
     q('Pokud technologie zcela nahradí rutinní činnost a ostatní vlivy se nemění, poptávka po této práci může…',['Posunout se doleva','Povinně zvýšit mzdu všem','Zůstat vždy stejná','Zmizet nabídka práce'],0,'Firmy při stejné mzdě potřebují méně práce v nahrazené činnosti.',2),
     q('Pokud AI zvýší mezní produkt zaměstnance, může se poptávka po jeho práci…',['Snížit vždy na nulu','Posunout doprava','Změnit v nabídku práce','Přestat být odvozená'],1,'Vyšší přínos pracovníka může podpořit jeho najímání.',2),
     q('Monopson na trhu práce znamená…',['Jediného významného zaměstnavatele v daném trhu','Jediného pracovníka','Mnoho vzájemně nezávislých firem','Volný vstup bez bariér'],0,'Monopson popisuje tržní sílu kupujícího, na trhu práce zaměstnavatele.')])

add('kapital','Trh kapitálu a úrok',
    'Úspory, investice, nominální a reálná úroková míra, důchod a bohatství.',
    ['Vysvětlit nabídku úspor a poptávku po investicích.','Odlišit reálný a nominální úrok.','Popsat vztah mezi úrokem a investicemi.'],
    [('Kapitál a financování','Kapitál ve výrobě zahrnuje například stroje, budovy a software. Na trhu zapůjčitelných fondů se střetávají úspory a poptávka po prostředcích na investice.'),
     ('Cena kapitálu','Úroková míra vyjadřuje cenu zapůjčených prostředků. Při vyšší úrokové míře se méně investičních projektů vyplatí.'),
     ('Nominální a reálný úrok','Nominální úrok je sazba sjednaná v penězích, reálný zohledňuje inflaci. Přibližně platí reálný úrok ≈ nominální úrok − inflace, přesnější vztah používá Fisherovu rovnici.')],
    ('Půjčka pro dílnu','Firma zvažuje nákup stroje financovaný úvěrem.','Při vyšším úroku roste cena financování a některé projekty už nemají dostatečný očekávaný výnos.','Vyšší úrok obvykle tlumí investiční poptávku.'),
    'Úroková míra na trhu zapůjčitelných fondů není totéž co mzda na trhu práce.',
    'Sýkora: Trh kapitálu a rozdělování důchodů, seminář č. 11; Dohnalová a Dobeš: Mikroekonomie I (2013), kap. 10.',
    [('Co je reálná úroková míra?','Nominální úrok očištěný o inflaci.'),('Co tvoří nabídku zapůjčitelných fondů?','Úspory domácností a dalších subjektů.'),('Co je investiční poptávka?','Poptávka firem po prostředcích na investiční projekty.'),('Důchod vs. bohatství?','Důchod je tok za období; bohatství je stav majetku k okamžiku.')],
    [q('Co je základním zdrojem nabídky zapůjčitelných fondů?',['Úspory','Dovoz','Daňová přiznání','Počet zaměstnanců'],0,'Uspořené prostředky mohou financovat investice.'),
     q('Při vyšší úrokové míře bývá poptávka po financování investic…',['Vyšší bez ohledu na výnosy','Nižší','Vždy nulová','Neměnná'],1,'Vyšší náklad financování snižuje počet výnosných projektů.'),
     q('Je-li nominální úrok 7 % a inflace 3 %, přibližná reálná úroková míra je…',['10 %','7 %','4 %','3 %'],2,'Přibližně 7 − 3 = 4 procentní body.',2),
     q('Co je bohatství oproti důchodu?',['Tok za kalendářní rok','Stav majetku v určitém okamžiku','Výše jedné mzdy','Růst cen'],1,'Bohatství je stavová veličina, důchod toková.'),
     q('Co patří mezi reálný kapitál používaný ve výrobě?',['Stroj a výrobní hala','Pouze bankovky','Pouze důchod domácnosti','Pouze úroková sazba'],0,'Stroje a budovy poskytují výrobní služby.'),
     q('Co při vyšší inflaci a stejném nominálním úroku obvykle nastane s reálným úrokem?',['Vzroste','Klesne','Zůstane vždy nulový','Vyrovná se mzdě'],1,'Inflace snižuje kupní sílu nominálního výnosu.')])

add('rovnovaha','Celková rovnováha a efektivnost',
    'Vazby trhů, Walrasova rovnováha a Paretova efektivnost.',
    ['Rozlišit dílčí a celkovou rovnováhu.','Popsat Paretovo zlepšení.','Vysvětlit propojenost trhů.'],
    [('Parciální a celková rovnováha','Parciální analýza zkoumá jeden trh při ostatních nezměněných podmínkách. Celková rovnováha sleduje propojené trhy současně: změna na jednom může působit na další.'),
     ('Walrasovský přístup','V modelu celkové rovnováhy se ceny přizpůsobují tak, aby se na trzích vyrovnávala nabídka a poptávka při vzájemných vazbách.'),
     ('Paretovská efektivnost','Alokace je Paretovsky efektivní, pokud nelze někomu polepšit bez zhoršení situace jiného. Efektivnost sama o sobě neříká, zda je rozdělení spravedlivé.')],
    ('Zdražení elektřiny','Energie zdraží pro domácnosti i továrny.','Rostou výrobní náklady, což ovlivní nabídku výrobků, zaměstnanost i spotřebitelské rozpočty.','Jeden cenový šok může zasáhnout více vzájemně provázaných trhů.'),
    'Paretova efektivnost a rovnost rozdělení nejsou synonyma.',
    'Sýkora: Celková rovnováha a tržní efektivnost, seminář č. 12; Dohnalová a Dobeš: Mikroekonomie I (2013), kap. 11.',
    [('Parciální rovnováha?','Analýza jednoho trhu při ostatních podmínkách neměnných.'),('Celková rovnováha?','Současné vyrovnání vzájemně propojených trhů.'),('Paretovo zlepšení?','Zlepšení situace alespoň jednoho bez zhoršení kohokoliv jiného.'),('Je Pareto efektivnost totéž co spravedlnost?','Ne, efektivní rozdělení může být velmi nerovné.')],
    [q('Co je hlavní rozdíl mezi parciální a celkovou rovnováhou?',['Parciální řeší jediný trh, celková vazby více trhů','Celková ignoruje trhy','Parciální zahrnuje všechny země','Neexistuje rozdíl'],0,'Celková analýza respektuje vzájemnou provázanost trhů.'),
     q('Kdy je alokace Paretovsky efektivní?',['Když mají všichni stejné příjmy','Když nelze nikomu polepšit bez zhoršení jiného','Když je maximální daň','Když je nulová nezaměstnanost'],1,'Definice Paretovy efektivnosti se týká možnosti nezhoršujícího zlepšení.'),
     q('Jaký je příklad vzájemné provázanosti trhů?',['Dražší energie mění výrobní náklady a ceny produktů','Cena energie neovlivní žádný další trh','Výrobní náklady jsou nezávislé na energiích','Spotřebitelé nemají rozpočet'],0,'Změny cen vstupů se promítají do produkce a dalších trhů.'),
     q('Je Paretovsky efektivní alokace automaticky sociálně spravedlivá?',['Ano, vždy','Ne, efektivnost a spravedlnost jsou odlišné pojmy','Jen pokud neexistují ceny','Jen při nulovém HDP'],1,'Paretovo kritérium neposuzuje, zda je rozdělení příjmů férové.'),
     q('Co charakterizuje celkovou rovnováhu v základním modelu?',['Ceny a množství se současně přizpůsobují napříč trhy','Každý trh je izolovaný','Neexistují výrobní faktory','Poptávka se nemůže změnit'],0,'Ceny koordinují chování subjektů napříč více trhy.'),
     q('Paretovo zlepšení nastane, pokud…',['Někdo získá a nikdo jiný neztratí','Všichni mají identickou mzdu','Stát zvýší daň','Všechny firmy maximalizují tržby'],0,'Jde o zlepšení alespoň jednoho bez újmy ostatních.')])

add('trzni-selhani','Tržní selhání a stát',
    'Externality, veřejné statky, informační asymetrie a důvody regulace.',
    ['Rozpoznat čtyři příčiny tržního selhání.','Vysvětlit pozitivní a negativní externalitu.','Popsat nástroje nápravy i jejich limity.'],
    [('Tržní selhání','Tržní mechanismus někdy nevede ke společensky efektivní alokaci. Může jít o tržní sílu, externality, veřejné statky nebo asymetrické informace.'),
     ('Externality a veřejné statky','Negativní externalita znamená, že činnost škodí třetím osobám bez odpovídající náhrady, například znečištění. Pozitivní externalita přináší přínos ostatním, například vzdělání. Čistě veřejný statek je nevylučitelný a nerivalitní.'),
     ('Role státu a limity','Daně, dotace, regulace či veřejné poskytování statků mohou řešit selhání. Zásahy však mají náklady a mohou samy vytvářet neefektivnosti; je třeba srovnat přínos a náklady.')],
    ('Továrna a ovzduší','Továrna vypouští emise, které zhoršují zdraví místních obyvatel.','Firma ve svých soukromých nákladech nezohlední veškeré společenské škody.','Emisní poplatky nebo jiná opatření mohou vnést vnější náklady do rozhodování firmy.'),
    'Veřejný statek není totéž co „cokoliv, co vlastní stát“. Rozhodující jsou ekonomické vlastnosti spotřeby.',
    'Sýkora: Tržní selhání a působení státu, seminář č. 13; Dohnalová a Dobeš: Mikroekonomie I (2013).',
    [('Co je negativní externalita?','Náklad uvalený na třetí osoby bez odpovídající kompenzace.'),('Co je veřejný statek?','Statkem v čisté podobě nevylučitelným a nerivalitním.'),('Asymetrické informace?','Jedna strana transakce má relevantně více informací než druhá.'),('Jak lze korigovat externalitu?','Například daní, dotací nebo regulací podle povahy externality.')],
    [q('Co je příkladem negativní externality?',['Vzdělávání s přínosy pro společnost','Kouř z továrny škodící sousedům','Dobrovolná sleva v obchodě','Růst produktivity firmy'],1,'Škoda dopadá na třetí osoby a tržní cena ji nemusí zohlednit.'),
     q('Který příklad nejlépe odpovídá čistému veřejnému statku?',['Soukromý mobil','Krajíc chleba','Národní obrana','Jedno sedadlo v kině'],2,'Národní obrana je obvykle nerivalitní a nelze z ní snadno vyloučit jednotlivce.'),
     q('Co znamená informační asymetrie?',['Obě strany znají přesně totéž','Jedna strana ví o podstatné vlastnosti více než druhá','Cena výrobku je pevná','Poptávka rovná se nabídka'],1,'Nerovnoměrné informace mohou narušit kvalitu rozhodování.'),
     q('Jaký nástroj může pomoci řešit negativní externalitu z emisí?',['Emisní daň','Dotace za další znečištění','Zákaz jakékoliv informace','Odstranění evidence emisí'],0,'Daň z externality může promítnout část společenských nákladů do ceny.'),
     q('Pozitivní externalitou vzdělání může být…',['Vyšší prospěch společnosti díky znalostem','Povinný růst emisí','Zhoršení informačních toků','Snížení lidského kapitálu'],0,'Vzdělání má vedle soukromých i společenské přínosy.'),
     q('Proč ani státní zásah není automaticky optimální?',['Regulace nemá žádné náklady','Existují informační omezení a náklady regulace','Stát nikdy nemůže vybírat daně','Veřejné statky nejsou dostupné'],1,'Vedle tržního selhání existuje i riziko neefektivní politiky.',2)])

add('ai-trh-prace','AI a budoucnost trhu práce',
    'Aplikace mikroekonomie: automatizace, augmentace, pracovní místa a česká data.',
    ['Odlišit pracovní úkol od celé profese.','Rozlišit skutečný údaj, očekávání firem a prognózu.','Posoudit substituci a doplnění lidské práce.'],
    [('Dvě cesty změny','Automatizace nahrazuje konkrétní úkoly, například třídění faktur. Augmentace pomáhá pracovníkovi zvýšit výkon, například při analýze dat. Dopad na zaměstnanost není automaticky totožný s dopadem na jednotlivé činnosti.'),
     ('České scénáře a časové horizonty','Studie BCG, MPSV a Aspen z roku 2025 modeluje do roku 2035 vznik 955 tisíc míst a zánik 355 tisíc; změny zahrnují více trendů, nejen AI. Průzkum ÚP ČR 2026 zjistil, že 61 % dotázaných zaměstnavatelů nečeká během dalších tří let významnou změnu počtu zaměstnanců kvůli AI.'),
     ('Dovednosti','V průzkumu ÚP ČR 2026 byly za důležité pro budoucnost nejčastěji označeny technické dovednosti (58 %), digitální gramotnost (50 %) a kreativní myšlení (47 %). Jde o odpovědi zaměstnavatelů, nikoliv naměřené dopady AI.')],
    ('Účetní oddělení','AI přečte příchozí faktury a navrhne jejich zaúčtování.','Člověk může kontrolovat chyby, řešit výjimky a věnovat se klientům. Firma také může potřebovat méně hodin rutinní práce.','Proměna náplně práce a zánik pracovního místa jsou odlišné události.'),
    'Neříkej, že „AI zruší 43 % míst“. BCG v daném údaji popisuje podíl profesí ovlivněných GenAI, ne podíl zaniklých míst.',
    'BCG, MPSV, Aspen Institute: Budoucnost českého pracovního trhu (2025), s. 20–21; Úřad práce ČR: Predikce a realita pracovního trhu očima zaměstnavatelů (2026), s. 25–29.',
    [('Automatizace práce?','Technologie přebírá některé úkoly, které dříve dělal člověk.'),('Augmentace práce?','Technologie podporuje lidskou práci a zvyšuje schopnost plnit úkoly.'),('Kolik firem nečekalo významnou změnu počtu lidí kvůli AI?','61 % v šetření ÚP ČR 2026, v horizontu tří let.'),('Prognóza BCG do 2035: vznik / zánik?','955 tisíc nových a 355 tisíc zaniklých pozic podle modelu.'),('Co je rekvalifikace?','Osvojení kompetencí pro jiné pracovní uplatnění.')],
    [q('Když chatbot převezme rutinní dotazy zákaznické podpory, jde primárně o…',['Substituci části lidské práce','Růst nabídky domácností','Snížení důchodového efektu','Vznik veřejného statku'],0,'Technologie přebírá konkrétní pracovní činnost.'),
     q('Když AI pomáhá specialistovi zpracovat více zakázek, jde především o…',['Monopson','Augmentaci','Důchodový efekt','Cenový strop'],1,'AI doplňuje člověka a podporuje jeho produktivitu.'),
     q('Co znamená, že pracovní místo je „ovlivněno GenAI“?',['Pracovní místo určitě zanikne','Všechny úkoly se zautomatizují','Některé činnosti se mohou změnit','Mzda musí být nulová'],2,'Expozice GenAI a zánik celé pozice nejsou totéž.'),
     q('Kolik zaměstnavatelů v šetření ÚP ČR 2026 neočekávalo významnou změnu počtu zaměstnanců kvůli AI během tří let?',['29 %','4 %','61 %','95 %'],2,'ÚP ČR uvádí 61 % respondentů, kteří nečekají významnou změnu.'),
     q('Jaký čistý přírůstek pracovních míst plyne z prognózy 955 tisíc nových a 355 tisíc zanikajících pozic?',['600 tisíc','355 tisíc','1 310 tisíc','955 tisíc'],0,'955 − 355 = 600 tisíc. Výhled zahrnuje více trendů než pouze AI.',2),
     q('Které dovednosti označili zaměstnavatelé v ÚP ČR 2026 nejčastěji jako důležité?',['Pouze cizí jazyky','Technické dovednosti','Pouze manažerské dovednosti','Jen práce v kanceláři'],1,'Technické dovednosti uvedlo 58 % zaměstnavatelů, nejvíce z nabídnutých možností.')],time=14)

